<script setup lang="ts">
import { computed, ref } from 'vue'
import { useStudyStore } from '../domain/store'
import AppIcon from './AppIcon.vue'
import AttachmentGallery from './AttachmentGallery.vue'
import { formatLocalDate } from '../utils/format'
const props = defineProps<{ id: string }>()
const emit = defineEmits<{ close: []; edit: [id: string]; editRemark: [id: string]; practice: [ids: string[]]; searchTag: [tag: string] }>()
const store = useStudyStore()
const q = computed(() => store.questions.value.find(item => item.id === props.id))
const pending = computed(() => q.value?.organizationStatus === 'pending')
const revealed = ref(false)
const expandedHistory = ref<string[]>([])
const history = computed(() => store.state.reviews.filter(item => item.questionId === props.id).slice().reverse())
function toggleHistory(id: string) { expandedHistory.value = expandedHistory.value.includes(id) ? expandedHistory.value.filter(item => item !== id) : [...expandedHistory.value, id] }
function remove() { uni.showModal({ title: '把这道题移入回收站？', content: '可以在回收站恢复，复习记录会保留。', confirmText: '移入回收站', success: async res => { if (res.confirm) { store.deleteQuestion(props.id); try { await store.flushPersistence(); emit('close'); uni.showToast({ title: '已移入回收站', icon: 'none' }) } catch (error) { uni.showToast({ title: error instanceof Error ? error.message : '保存未完成', icon: 'none' }) } } } }) }
async function setDate(event: any) { store.setPlan(props.id, event.detail.value); try { await store.flushPersistence(); uni.showToast({ title: '复习日期已安排', icon: 'success' }) } catch (error) { uni.showToast({ title: error instanceof Error ? error.message : '日期尚未保存', icon: 'none' }) } }
function previewImage(image: string) { if (q.value) uni.previewImage({ urls: q.value.images, current: image }) }
</script>

<template>
  <view class="modal-overlay" @tap.self="emit('close')"><view class="modal-window detail-window">
    <view class="modal-header"><view><text class="eyebrow">ONE QUESTION, ONE STEP</text><text class="modal-title">题目档案</text></view><view class="header-actions"><button v-if="q" class="icon-button" :aria-label="q.favorite ? '取消收藏' : '收藏'" @tap="store.toggleFavorite(q.id)"><AppIcon :name="q.favorite ? 'bookmark-check' : 'bookmark'" :tone="q.favorite ? 'orange' : 'muted'" /></button><button class="icon-button" aria-label="关闭" @tap="emit('close')"><AppIcon name="x" /></button></view></view>
    <scroll-view v-if="q" scroll-y class="modal-scroll"><view class="detail-content">
      <view class="detail-meta"><text class="badge">{{ q.subject || '待分类' }}</text><text class="badge badge-neutral">{{ q.difficulty || '难度待定' }}</text><text class="detail-status" :class="{ mastered: !pending && q.status === 'mastered' }">{{ pending ? '待处理' : q.status === 'mastered' ? '已掌握' : '待巩固' }}</text></view>
      <text class="detail-title">{{ q.title }}</text><text class="detail-source">{{ q.source || '自主收录' }} · {{ formatLocalDate(q.createdAt) }}</text>
      <view class="problem-sheet"><view class="sheet-label"><AppIcon name="file-text" :size="15" tone="muted" /><text>原题</text></view><text class="problem-stem">{{ q.stem }}</text><image v-for="image in q.images" :key="image" :src="image" mode="widthFix" class="detail-image" @tap="previewImage(image)" /></view>
      <view v-if="q.userAnswer" class="original-answer"><view><AppIcon name="pencil" :size="15" tone="orange" /><text>当时的作答</text><text class="original-answer-hint">回看思考，找到卡住的那一步</text></view><text>{{ q.userAnswer }}</text></view>
      <view class="detail-tags"><button v-for="tag in q.tags" :key="tag" class="filter-chip detail-tag" :aria-label="`查找标签 ${tag} 的相关错题`" @tap="emit('searchTag', tag)"># {{ tag }}</button></view>
      <view v-if="pending" class="detail-pending-note"><view class="detail-pending-symbol"><AppIcon name="folder-open" :size="25" tone="orange" /></view><view><text>题目已收好，整理可以慢慢来。</text><text>点击继续整理，可手动补充或使用 AI 辅助整理，核对后确认入库。</text></view></view>
      <button v-else-if="!revealed" class="answer-reveal" @tap="revealed = true"><AppIcon name="lightbulb" :size="18" tone="green" /><view><text class="reveal-title">先想一想，再看答案</text><text class="reveal-sub">点击展开参考答案与解题解析</text></view><AppIcon name="chevron-down" :size="18" tone="muted" /></button>
      <view v-else-if="!pending" class="answer-block"><text class="field-label">参考答案</text><text class="answer-text">{{ q.answer || '暂未补充参考答案，点击编辑完善。' }}</text><text class="field-label answer-label">解题解析</text><text class="analysis-text">{{ q.analysis || '暂未补充解题解析，点击编辑完善。' }}</text></view>
      <view class="detail-remark-section">
        <view class="detail-remark-heading"><view><AppIcon name="notebook-pen" :size="17" tone="green" /><text>补充说明</text></view><button class="text-button detail-remark-edit" aria-label="编辑补充说明" @tap="emit('editRemark', q.id)"><AppIcon name="pencil" :size="13" tone="green" /><text>{{ q.remark || q.remarkImages?.length ? '编辑' : '添加补充说明' }}</text></button></view>
        <text v-if="q.remark" class="detail-remark-text">{{ q.remark }}</text>
        <text v-if="!q.remark && !q.remarkImages?.length" class="detail-remark-empty">把板书、草稿和自己的理解，留在这道题旁边。</text>
        <AttachmentGallery v-if="q.remarkImages?.length" :model-value="q.remarkImages" readonly label="备注附图" />
      </view>
      <view v-if="!pending" class="plan-row"><view class="plan-row-label"><AppIcon name="calendar-days" :size="18" tone="green" /><text>安排下一次复习</text></view><picker mode="date" :value="q.nextReviewDate || ''" @change="setDate"><view class="date-picker-value">{{ q.nextReviewDate || '选择日期' }}<AppIcon name="chevron-right" :size="14" tone="muted" /></view></picker></view>
      <view v-if="!pending && q.nextReviewDate" class="plan-clear-row"><button class="text-button muted" @tap="store.setPlan(q.id, null)">取消此次计划</button></view>
      <view v-if="!pending" class="history-heading"><text class="field-label">复习足迹</text><text class="muted small">{{ history.length }} 次记录</text></view>
      <view v-if="!pending && !history.length" class="history-empty"><AppIcon name="clock-3" :size="24" tone="muted" /><text>还没有复习记录，从第一次独立重做开始。</text></view>
      <view v-for="record in history.slice(0, 8)" :key="record.id" class="history-item"><view class="history-dot" :class="{ correct: record.rating !== 'wrong' }" /><view><text class="history-rating">{{ record.rating === 'wrong' ? '还需要巩固' : record.rating === 'mastered' ? '独立完成，已掌握' : '答对了，继续巩固' }}</text><text v-if="record.answer" class="history-answer">我的作答：{{ record.answer }}</text><button v-if="record.questionSnapshot" class="history-snapshot-button" @tap="toggleHistory(record.id)">{{ expandedHistory.includes(record.id) ? '收起当时题面' : '查看当时题面' }}</button><view v-if="record.questionSnapshot && expandedHistory.includes(record.id)" class="history-snapshot"><text>{{ record.questionSnapshot.title }}</text><text>{{ record.questionSnapshot.stem }}</text><text>当时参考答案：{{ record.questionSnapshot.answer }}</text></view></view><text class="history-date">{{ formatLocalDate(record.reviewedAt || '', true) }}</text></view>
    </view></scroll-view>
    <view v-else class="empty-state">这道题已被移入回收站。</view>
    <view v-if="q" class="modal-footer detail-footer"><button class="icon-button delete-button" aria-label="移入回收站" @tap="remove"><AppIcon name="trash-2" :size="18" tone="muted" /></button><button v-if="!pending" class="button button-quiet" @tap="emit('edit', q.id)"><AppIcon name="pencil" :size="15" /><text>编辑</text></button><button v-if="pending" class="button button-primary" @tap="emit('edit', q.id)"><AppIcon name="notebook-pen" :size="16" tone="white" /><text>继续整理</text></button><button v-else class="button button-primary" @tap="emit('practice', [q.id])"><AppIcon name="refresh-cw" :size="16" tone="white" /><text>独立重做</text></button></view>
  </view></view>
</template>

<style scoped>
.detail-remark-section{background:#fafbf6;border:1px solid #e4eadc;border-radius:13px;padding:18px;margin:20px 0 9px}.detail-remark-heading,.detail-remark-heading>view{display:flex;align-items:center;gap:7px}.detail-remark-heading{justify-content:space-between;color:#4b7150;font-size:12px;font-weight:550}.detail-remark-edit{display:flex;align-items:center;gap:5px;font-size:10px;font-weight:400;padding:3px 0;margin:0}.detail-remark-text{display:block;white-space:pre-wrap;word-break:break-word;font-size:13px;line-height:1.9;color:#6b7d61;margin-top:13px}.detail-remark-empty{display:block;font-size:11px;color:#99a28e;line-height:1.9;margin-top:12px}@media(max-width:600px){.detail-remark-section{padding:15px}}
.history-snapshot-button{font-size:10px;padding:0;margin:7px 0 0;color:#7a9866;background:none;text-align:left}.history-snapshot{background:#f6f9ef;border:1px solid #e6edda;border-radius:7px;padding:12px;margin-top:9px;max-width:400px}.history-snapshot>text{display:block;font-size:11px;line-height:1.8;white-space:pre-wrap;color:#859575;margin-top:5px}.detail-window{width:690px}.header-actions{display:flex;gap:7px}.detail-content{padding:25px 30px 35px}.detail-meta{display:flex;align-items:center;gap:7px}.detail-status{margin-left:auto;font-size:11px;color:#b37c45}.detail-status.mastered{color:#578965}.detail-title{font-size:23px;line-height:1.55;font-weight:650;display:block;margin:20px 0 7px;letter-spacing:-.6px}.detail-source{font-size:11px;color:#9ba394}.problem-sheet{background:#f7f8f2;border-radius:12px;padding:21px;margin:24px 0 16px;border:1px solid #edf0e5;background-image:linear-gradient(#e5e9dd40 1px,transparent 1px);background-size:100% 28px}.sheet-label{display:flex;align-items:center;gap:6px;font-size:10px;color:#909b87;margin-bottom:15px}.problem-stem{display:block;line-height:2;font-family:Georgia,'PingFang SC',serif;font-size:16px;white-space:pre-wrap}.detail-image{display:block;width:100%;margin-top:15px;border-radius:6px}.detail-tags{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:25px}.answer-reveal{display:flex;align-items:center;text-align:left;background:#f0f5ec;padding:17px;gap:12px;border-radius:10px;margin:0;width:100%}.answer-reveal>.app-icon:last-child{margin-left:auto}.reveal-title{display:block;font-size:13px;color:#3d684c;font-weight:600}.reveal-sub{display:block;font-size:10px;color:#94a08c;margin-top:4px}.answer-block{padding:20px;border:1px solid #dce8d5;background:#f9fcf5;border-radius:12px}.answer-text,.analysis-text{display:block;line-height:1.9;white-space:pre-wrap;font-size:14px}.answer-text{font-weight:600;color:#3b6d49;margin-top:8px}.analysis-text{color:#75816f;font-size:13px;margin-top:8px}.answer-label{margin-top:23px!important}.plan-row{display:flex;align-items:center;justify-content:space-between;padding:20px 0 8px;gap:12px}.plan-row-label{display:flex;align-items:center;gap:8px;font-size:12px}.date-picker-value{display:flex;align-items:center;gap:7px;color:#73836c;font-size:12px}.plan-clear-row{display:flex;justify-content:flex-end}.history-heading{display:flex;justify-content:space-between;margin:28px 0 15px}.history-empty{display:flex;gap:10px;align-items:center;background:#f8f9f4;border-radius:10px;padding:18px;color:#99a18f;font-size:11px}.history-item{display:flex;align-items:flex-start;gap:9px;border-bottom:1px solid #f0f1eb;padding:13px 0}.history-dot{width:6px;height:6px;background:#d7aa76;border-radius:50%;margin-top:5px;flex-shrink:0}.history-dot.correct{background:#7fa07a}.history-rating{font-size:12px;display:block}.history-answer{display:block;font-size:11px;color:#909b85;max-width:350px;margin-top:5px;line-height:1.7}.history-date{margin-left:auto;white-space:nowrap;font-size:10px;color:#a1a894}.delete-button{margin-right:auto;color:#9ba28f}.detail-footer{gap:10px}.small{font-size:11px}@media(max-width:600px){.detail-content{padding:20px}.detail-title{font-size:21px}.problem-stem{font-size:15px}.history-answer{max-width:190px}.detail-footer .button{padding:11px 17px}}
</style>

<style scoped>
.original-answer{background:#fcf7ee;border:1px solid #efe5d5;border-radius:11px;padding:17px 19px;margin-bottom:17px}.original-answer>view{display:flex;align-items:center;gap:6px;color:#b08b57;font-size:11px;font-weight:550;margin-bottom:10px}.original-answer-hint{margin-left:auto;font-size:9px;font-weight:400;color:#bdab91}.original-answer>text{display:block;font-size:13px;line-height:1.9;color:#9a815f;white-space:pre-wrap}@media(max-width:600px){.original-answer{padding:15px 16px}.original-answer-hint{display:none}}

.detail-pending-note{display:flex;align-items:flex-start;gap:13px;background:#faf6e9;border:1px solid #eae3cb;border-radius:12px;padding:19px;margin:21px 0 7px}.detail-pending-symbol{flex-shrink:0;display:flex;align-items:center;justify-content:center;width:41px;height:41px;background:#f2e8cf;border-radius:12px}.detail-pending-note>view:last-child{min-width:0}.detail-pending-note>view:last-child>text:first-child{display:block;font-size:13px;font-weight:550;color:#7d794d;line-height:1.8}.detail-pending-note>view:last-child>text:last-child{display:block;font-size:11px;color:#9b9a7c;line-height:1.9;margin-top:5px}@media(max-width:600px){.detail-pending-note{padding:15px;gap:10px}.detail-pending-note>view:last-child>text:first-child{font-size:12px}.detail-pending-note>view:last-child>text:last-child{font-size:10px}.detail-footer .button{font-size:11px;padding:11px 13px}.detail-footer{gap:7px}}
</style>
